// NORMALIZAR
// Toda la diferencia entre proveedores vive AQUI y solo aqui.

const hoy = new Date().toISOString().slice(0, 10);
const empresas = $('Leer empresas').all();
const respuestas = $input.all();

if (empresas.length !== respuestas.length) {
  throw new Error(
    `Desalineacion: ${empresas.length} empresas vs ${respuestas.length} respuestas`
  );
}

// Greenhouse devuelve HTML escapado. Lo limpiamos y recortamos:
// el LLM no necesita 12.000 caracteres para decidir, y los tokens cuestan.
const limpiar = (html) => {
  if (!html) return '';
  return html
    .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')
    .replace(/&nbsp;/g, ' ').replace(/&#39;/g, "'").replace(/&quot;/g, '"')
    .replace(/<[^>]+>/g, ' ')      // fuera etiquetas
    .replace(/\s+/g, ' ')          // espacios colapsados
    .trim()
    .slice(0, 3500);               // techo duro de contexto
};

const mapeo = {
  greenhouse: (v) => ({
    id_externo: String(v.id),
    titulo: v.title,
    ubicacion: v.location?.name ?? 'sin especificar',
    url: v.absolute_url,
    descripcion: limpiar(v.content)
  }),
  lever: (v) => ({
    id_externo: v.id,
    titulo: v.text,
    ubicacion: v.categories?.location ?? 'sin especificar',
    url: v.hostedUrl,
    descripcion: limpiar(v.descriptionPlain)
  }),
  ashby: (v) => ({
    id_externo: v.id,
    titulo: v.title,
    ubicacion: v.location ?? 'sin especificar',
    url: v.jobUrl,
    descripcion: limpiar(v.descriptionPlain ?? v.descriptionHtml)
  })
};

const salida = [];
const omitidas = [];

respuestas.forEach((res, i) => {
  const { empresa, fuente } = empresas[i].json;

  if (!mapeo[fuente]) {
    omitidas.push(`${empresa}: fuente '${fuente}' sin mapeo`);
    return;
  }

  const vacantes = res.json?.jobs ?? (Array.isArray(res.json) ? res.json : []);

  vacantes.forEach((v) => {
    const base = mapeo[fuente](v);

    if (!base.titulo) {
      omitidas.push(`${empresa}: vacante ${base.id_externo} sin titulo`);
      return;
    }

    salida.push({
      json: {
        ...base,
        empresa,
        fuente,
        clave: `${fuente}:${empresa}:${base.id_externo}`,
        huella: `${empresa}:${base.titulo.toLowerCase().replace(/[^a-z0-9]/g, '')}`,
        descubierta: hoy,
        estado: 'nueva'
      }
    });
  });
});

if (omitidas.length) {
  console.log(`OMITIDAS (${omitidas.length}):\n` + omitidas.join('\n'));
}
// Chequeo rapido: si esto sale en 0, el content=true no esta llegando.
const conDesc = salida.filter((x) => x.json.descripcion.length > 100).length;
console.log(`Normalizadas: ${salida.length} | con descripcion: ${conDesc}`);

return salida;

// DEDUPLICAR
const registro = $input.all();

// El item vacio de "Always Output Data" llega sin clave.
// Lo filtramos aqui para que no contamine los sets.
const filas = registro.filter((r) => r.json?.clave);

// Set en vez de array: busqueda O(1) en vez de O(n).
const clavesVistas = new Set(filas.map((r) => r.json.clave));
const huellasVistas = new Set(filas.map((r) => r.json.huella));

const todas = $('Normalizar').all();
const nuevas = todas.filter(
  (v) => !clavesVistas.has(v.json.clave) && !huellasVistas.has(v.json.huella)
);

console.log(`Registro: ${filas.length} | Revisadas: ${todas.length} | Nuevas: ${nuevas.length}`);

return nuevas;

// PREFILTRO — capa 0
// No descarta: MARCA. Todas se guardan para no perder la deduplicacion.

const LISTA_BLANCA = [
  'engineer', 'developer', 'desarrollador', 'ingeniero',
  'automation', 'automatizacion', 'integration', 'integraciones',
  'backend', 'full stack', 'fullstack',
  'python', 'api', 'data', 'ai', 'ml',
  'software', 'technical', 'solutions', 'platform',
  'n8n', 'workflow', 'rpa', 'no-code', 'low-code'
];

// Ubicaciones donde SI eres elegible.
const UBIC_FUERTE = ['colombia', 'bogota', 'medellin', 'latam', 'latin america'];
// Remoto sin pais: ambiguo, pasa y lo resuelve la capa 1 leyendo la descripcion.
const UBIC_AMBIGUA = ['remote', 'remoto', 'anywhere', 'global', 'worldwide', 'americas'];
// Excepcion consciente al principio de "lista blanca": estos paises aparecen
// como "Remote - X" y son remotos pero no contratan desde Colombia.
// Es lista negra a proposito y por eso NO descarta sola: solo aplica cuando
// la ubicacion no matcheo antes contra UBIC_FUERTE.
const UBIC_BLOQUEO = [
  'united states', 'usa', 'canada', 'united kingdom',
  'brazil', 'brasil', 'mexico', 'argentina', 'chile', 'peru',
  'india', 'turkey', 'turkiye', 'europe', 'germany', 'spain', 'poland'
];
// Siglas: se comparan con limite de palabra para no pegar dentro de otra
// (sin esto 'uk' matchea "Ukraine" y 'us' matchea "ustedes", "industry"...).
const UBIC_BLOQUEO_SIGLAS = ['us', 'uk', 'eu', 'emea'];

// Quita tildes y baja a minusculas: "Medellín" y "medellin" deben ser lo mismo.
const norm = (t) =>
  (t ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// Compara con limite de palabra. Sin esto 'api' matchea "therAPIst",
// 'ml' matchea "htML" y 'ai' matchea "chAIr": basura que pasa el filtro.
const escapar = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const contiene = (texto, termino) =>
  new RegExp(`\\b${escapar(termino)}\\b`).test(texto);
const contieneAlguno = (texto, lista) => lista.some((t) => contiene(texto, t));

let pasan = 0;

const salida = $input.all().map((item) => {
  const titulo = norm(item.json.titulo);
  const ubic = norm(item.json.ubicacion);

  const tituloOk = contieneAlguno(titulo, LISTA_BLANCA);

  let ubicOk, notaUbic;
  if (contieneAlguno(ubic, UBIC_FUERTE)) {
    ubicOk = true;  notaUbic = 'ubicacion compatible';
  } else if (contieneAlguno(ubic, UBIC_BLOQUEO) ||
             contieneAlguno(ubic, UBIC_BLOQUEO_SIGLAS)) {
    ubicOk = false; notaUbic = 'jurisdiccion incompatible';
  } else if (contieneAlguno(ubic, UBIC_AMBIGUA)) {
    ubicOk = true;  notaUbic = 'remoto sin pais, revisar en capa 1';
  } else {
    ubicOk = false; notaUbic = 'ubicacion no reconocida';
  }

  const pasa = tituloOk && ubicOk;
  if (pasa) pasan++;

  return {
    json: {
      ...item.json,
      prefiltro: pasa ? 'si' : 'no',
      motivo: pasa ? notaUbic : (!tituloOk ? 'titulo fuera de perfil' : notaUbic)
    }
  };
});

console.log(`Prefiltro: ${pasan} de ${salida.length} pasan`);

return salida;

// SCORING 2a — determinista, sin LLM.
// Todo lo que se puede medir buscando texto, se mide aqui.

const PERFIL = {
  stack_fuerte: ['n8n', 'python', 'rest api', 'api', 'webhook', 'llm', 'openai',
                 'anthropic', 'prompt', 'automation', 'automatizacion', 'integration'],
  stack_solido: ['javascript', 'fastapi', 'git', 'postman', 'sql', 'mysql', 'sqlite'],
  stack_basico: ['typescript', 'html', 'css', 'docker', 'railway'],
  sectores: ['construction', 'construccion', 'insurance', 'insurtech', 'seguros',
             'logistics', 'logistica', 'supply chain', 'customs', 'trade',
             'food', 'manufacturing', 'fintech'],
  anos_dev: 2
};

// Un match perfecto contra tu stack ronda 25 puntos brutos.
// Dividir por esa referencia estira la escala: antes bastaban 5 terminos
// fuertes para topar en 10 y toda vacante de backend empataba arriba.
const BRUTO_DE_REFERENCIA = 25;

const norm = (t) => (t ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

// Limite de palabra obligatorio: sin el, 'api' matchea "therAPIst",
// 'ml' matchea "htML" y 'ai' matchea "chAIr".
const escapar = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const contar = (texto, lista) =>
  lista.filter((t) => new RegExp(`\\b${escapar(t)}\\b`).test(texto)).length;

return $input.all().map((item) => {
  const texto = norm(item.json.titulo + ' ' + (item.json.descripcion ?? ''));
  const titulo = norm(item.json.titulo);
  const banderas = [];

  // --- STACK: pesos distintos segun dominio real ---
  const f = contar(texto, PERFIL.stack_fuerte);
  const s = contar(texto, PERFIL.stack_solido);
  const b = contar(texto, PERFIL.stack_basico);
  const bruto = f * 2 + s * 1 + b * 0.5;
  const stack = Math.min(10, Math.round((bruto / BRUTO_DE_REFERENCIA) * 100) / 10);

  // --- SENIORITY: el titulo manda ---
  // 'junior' no vale mas que 'mid': con 25 anos de trayectoria un internship
  // no es mejor match que un mid, solo es mas facil de conseguir.
  let seniority = 5;
  if (/\b(junior|jr\.?|entry[- ]level|trainee)\b/.test(titulo)) seniority = 9;
  else if (/\b(intern|internship)\b/.test(titulo)) seniority = 4;
  else if (/\b(ii|mid|mid[- ]level|semi[- ]?senior)\b/.test(titulo)) seniority = 10;
  else if (/\b(senior|sr\.?|iii)\b/.test(titulo)) seniority = 4;
  if (/\b(staff|principal|lead|architect|head of|director|manager|vp)\b/.test(titulo)) {
    seniority = 0;
    banderas.push('KNOCKOUT: seniority fuera de alcance');
  }

  // --- CONTEXTO DE NEGOCIO: tu diferenciador real ---
  const contexto = Math.min(10, contar(texto, PERFIL.sectores) * 4);

  // --- ANOS: marca brecha, no descarta. La evidencia puede compensar. ---
  // Buscamos TODAS las apariciones y nos quedamos con la menor: una oferta que
  // dice "5 years in business ... 2 years of experience" pide 2, no 5.
  const pedidos = [...texto.matchAll(/(\d{1,2})\s*\+?\s*(?:years?|yrs?|anos)\b(?![^.]{0,40}\b(?:in business|of history|founded)\b)/g)]
    .map((m) => parseInt(m[1], 10))
    .filter((n) => n > 0 && n <= 20);
  if (pedidos.length) {
    const min = Math.min(...pedidos);
    if (min > PERFIL.anos_dev) {
      banderas.push(`BRECHA: piden ${min} anos, tienes ${PERFIL.anos_dev}`);
    }
  }

  // --- INGLES: marca riesgo de entrevista, NUNCA descarta ---
  if (/fluent english|advanced english|english.{0,10}c[12]|native english|excellent (written and )?(verbal )?english/.test(texto)) {
    banderas.push('RIESGO: exigen ingles alto');
  }

  // --- KNOCKOUTS DUROS ---
  // Solo patrones inequivocos. Un knockout por substring sobre 3500 caracteres
  // mata vacantes remotas que apenas mencionan una oficina: falso negativo caro.
  if (/\b(authorized to work in|work authorization|must be (?:a )?(?:us|u\.s\.) (?:citizen|resident)|must reside in the (?:united states|us|uk))\b/.test(texto)) {
    banderas.push('KNOCKOUT: exige autorizacion laboral');
  }
  if (/\b(commission[- ]only|solo comision)\b/.test(texto)) {
    banderas.push('KNOCKOUT: solo comision');
  }

  // Presencial: RIESGO, no KNOCKOUT. Se degrada a knockout solo con
  // una exigencia explicita de presencia. La capa 2b lo confirma leyendo.
  const remotoExplicito = /\b(fully remote|100% remote|remote[- ]first|work from anywhere|fully distributed)\b/.test(texto);
  const presencialDuro = /\b(?:\d+ days? (?:per|a) week (?:in|at) the office|must (?:be able to )?relocate|required to work on[- ]?site|on[- ]?site position|this is (?:a |an )?(?:hybrid|on[- ]?site) (?:role|position))\b/.test(texto);
  const presencialBlando = /\b(on[- ]?site|in[- ]?office|hybrid|relocation)\b/.test(texto);

  if (presencialDuro && !remotoExplicito) {
    banderas.push('KNOCKOUT: presencial o hibrido exigido');
  } else if (presencialBlando && !remotoExplicito) {
    banderas.push('RIESGO: menciona presencial/hibrido, confirmar en la descripcion');
  }

  const esKnockout = banderas.some((x) => x.startsWith('KNOCKOUT'));

  // Ponderacion: el stack pesa mas que todo lo demas junto.
  const puntaje = esKnockout
    ? 0
    : Math.round((stack * 0.5 + seniority * 0.3 + contexto * 0.2) * 10) / 10;

  return {
    json: {
      ...item.json,
      puntaje,
      desglose: `stack ${stack.toFixed(1)} (bruto ${bruto.toFixed(1)}) | seniority ${seniority} | contexto ${contexto}`,
      banderas: banderas.join(' || ') || 'sin banderas'
    }
  };
});
